#include <stdio.h>
int main() {
    int var = 10;  // Declare and initialize a variable
    int *ptr = &var;  // Pointer holds the address of var
    printf("Address of var: %p\n", (void*)ptr);  // Print the address
    printf("Value at address: %d\n", *ptr);  // Access value via pointer
    return 0;
}
